--
-- Table structure for table `podcast_appearances`
--

CREATE TABLE `podcast_appearances` (
  `id` smallint(5) UNSIGNED NOT NULL COMMENT 'Unique identifier',
  `person_id` smallint(4) UNSIGNED DEFAULT NULL COMMENT 'Person identifier',
  `podcast` enum('Taskmaster: The Podcast','Taskmaster: The People’s Podcast','Absolute Casserole- A Taskmaster Podcast','Taskmaster World The Podcast','Kongen Befaler - The Podcast') COLLATE utf8_unicode_ci DEFAULT NULL COMMENT 'Which podcast was this?',
  `episode_date` date DEFAULT NULL COMMENT 'Episode date',
  `episode_title` varchar(256) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT 'Episode title',
  `episode_link` varchar(256) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT 'Episode link'
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

